Method.Source:
/// <summary>
/// PaffH 04.08.22
/// </summary>
/// <param name = "_errorMessageCategory">NDXErrorMessageCategory</param>
/// <param name = "_errorMessageDetail">NDXErrorMessageDetail</param>
/// <returns>NDXErrorMessageClass</returns>
public static NDXErrorMessageClass construct(NDXErrorMessageCategory _errorMessageCategory, NDXErrorMessageDetail _errorMessageDetail)
{
    NDXErrorMessageClass nDXErrorMessageClass = new NDXErrorMessageClass();
    nDXErrorMessageClass.errorMessageCategory = _errorMessageCategory;
    nDXErrorMessageClass.errorMessageDetail = _errorMessageDetail;
    return nDXErrorMessageClass;
}

/// <summary>
/// PaffH 04.08.22
/// </summary>
/// <param name = "_errorMessageCategory">NDXErrorMessageCategory</param>
/// <returns>sNDXErrorMessageCategorytr</returns>
public NDXErrorMessageCategory parmErrorMessageCategory(NDXErrorMessageCategory _errorMessageCategory = errorMessageCategory)
{
    errorMessageCategory = _errorMessageCategory;
    return errorMessageCategory;
}

/// <summary>
/// PaffH 04.08.22
/// </summary>
/// <param name = "_errorMessageDetail">NDXErrorMessageDetail</param>
/// <returns>NDXErrorMessageDetail</returns>
public NDXErrorMessageDetail parmErrorMessageDetail(NDXErrorMessageDetail _errorMessageDetail = errorMessageDetail)
{
    errorMessageDetail = _errorMessageDetail;
    return errorMessageDetail;
}

/// <summary>
/// PaffH 04.08.22
/// </summary>
/// <param name = "_errorMessageMemo">NDXErrorMessageMemo</param>
/// <returns>NDXErrorMessageMemo</returns>
public NDXErrorMessageMemo parmErrorMessageMemo(NDXErrorMessageMemo _errorMessageMemo = errorMessageMemo)
{
    errorMessageMemo = _errorMessageMemo;
    return errorMessageMemo;
}
